import {POWER_PLANTS,plantCapacity} from './power.js?v=keyboard-construction-1';
const number=n=>n.toLocaleString('en-US',{maximumFractionDigits:1});
export function gridStatus(grid){return grid.maxStress>=4&&grid.load>1?'Failure risk':grid.unpowered?'Blackout':grid.demand===0?'No demand':grid.margin<=grid.demand*.1?'Limited reserve':'Supplied';}
export function plantPlanning(city){return city.tiles.filter((t,i)=>POWER_PLANTS[t.type]&&t.root===i).map(t=>{const d=POWER_PLANTS[t.type],potential=Math.round(d.capacity*(t.type==='wind'?1+(t.elevation||0)*.1:1));return{tile:t.y*city.size+t.x,name:d.name,age:t.age,current:plantCapacity(t),potential,nextYear:plantCapacity({...t,age:t.age+12}),stress:t.stress,grid:t.powerNetwork,cost:d.cost};}).sort((a,b)=>b.stress-a.stress||b.age-a.age||a.tile-b.tile);}
export function powerGridReport(city){const grids=city.stats.powerNetworks||[],plants=plantPlanning(city);return `<h3>Electrical grids</h3><p>Each connected grid must cover its own demand. Supply and demand are measured in game power units. The margin is available supply minus demand after current imports and exports; capacity elsewhere cannot fill a local shortage. Grid numbers are recalculated as connections change.</p><div class="table-scroll" style="max-height:360px;overflow:auto"><table><thead><tr><th>Grid</th><th>Status</th><th>Domestic capacity</th><th>Imports / exports</th><th>Demand / served</th><th>Margin</th><th>Unpowered lots</th><th>Location</th></tr></thead><tbody>${grids.map(g=>`<tr><td>${g.id+1}</td><td>${gridStatus(g)}</td><td>${number(g.nativeCapacity)}</td><td>${number(g.imported)} / ${number(g.exported)}</td><td>${number(g.demand)} / ${number(g.served)}</td><td>${g.margin>0?'+':''}${number(g.margin)}</td><td>${g.unpowered}</td><td><button data-power-location="${g.anchor}">View ${g.unpowered?'blackout':'grid'}</button></td></tr>`).join('')||'<tr><td colspan="8">No electrical grids yet. Build a power source and connect your zones.</td></tr>'}</tbody></table></div><p>Unpowered lots count demand-bearing zones and buildings, including empty zoning. “Failure risk” means a plant has spent at least four consecutive months overloaded; the sixth destroys it. Restoring sufficient grid supply before the next monthly check resets that streak.</p><h3>Plant replacement planning</h3><div class="table-scroll" style="max-height:360px;overflow:auto"><table><thead><tr><th>Plant / grid</th><th>Age</th><th>Capacity / new</th><th>In 12 months</th><th>Overload</th><th>Rebuild cost</th><th>Inspect</th></tr></thead><tbody>${plants.map(p=>`<tr><td>${p.name} · ${p.grid+1}</td><td>${number(p.age/12)} years</td><td>${number(p.current)} / ${number(p.potential)}</td><td>${number(p.nextYear)}</td><td>${p.stress} / 6 months</td><td>§${number(p.cost)}</td><td><button data-power-inspect="${p.tile}">Inspect plant</button></td></tr>`).join('')||'<tr><td colspan="7">No power plants. Imports and waste-to-energy may still supply your city.</td></tr>'}</tbody></table></div><p>The 12-month figure isolates normal aging at the current elevation. It assumes the plant survives and does not predict demand, construction or trade changes. Rebuild cost excludes demolition. Add replacement capacity before removing an old plant to avoid an interruption. Waste-to-energy is included in grid capacity using last month’s actual fuel throughput, rather than in this plant-aging table.</p>`;}
export function installPowerGridLinks(city,visit,root=document){
 for(const [attribute,inspect] of [['power-location',false],['power-inspect',true]])root.querySelectorAll(`[data-${attribute}]`).forEach(button=>{button.onclick=()=>{const index=Number(button.getAttribute('data-'+attribute)),tile=city.tiles[index];if(!Number.isInteger(index)||!tile)return;visit({x:tile.x,y:tile.y},inspect);};});
}
export function powerGridSummary(city,tile){const g=city.stats.powerNetworks?.[tile.powerNetwork];return g?`<p>Electrical grid ${g.id+1}: ${number(g.available)} available supply / ${number(g.demand)} demand; ${g.unpowered} unpowered lots. Domestic capacity ${number(g.nativeCapacity)}, imports ${number(g.imported)}, exports ${number(g.exported)}. Spare capacity on other grids does not reach this plant’s neighborhood.</p>`:'';}
